import React, { useState, useEffect } from "react";
import axios from "axios";
import "bootstrap/dist/css/bootstrap.min.css";
import live from "../../img/aulas-ao-vivo-coursifyme.jpg";

const LecionaAula = () => {
  const [materiais, setMateriais] = useState([]);
  const [cursos, setCursos] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");
  const [aulas, setAulas] = useState([]);
  const [novaAula, setNovaAula] = useState({
    titulo: "",
    arquivo: null,
  });
  const [novoMaterial, setNovoMaterial] = useState({
    nome: "",
    arquivo: null,
  });

  // Carregar cursos, materiais e aulas
  useEffect(() => {
    const carregarCursos = async () => {
      try {
        const response = await axios.get("/api/professores/me/cursos"); // Você precisará criar esta rota
        setCursos(response.data);
      } catch (error) {
        console.error("Erro ao carregar cursos:", error);
      }
    };

    carregarCursos();
  }, []);

  // Carregar materiais e aulas quando o curso for selecionado
  useEffect(() => {
    if (cursoSelecionado) {
      const carregarDados = async () => {
        try {
          const [materiaisResponse, aulasResponse] = await Promise.all([
            axios.get(`/api/materiais/curso/${cursoSelecionado}`),
            axios.get(`/api/aulas/curso/${cursoSelecionado}`),
          ]);
          setMateriais(materiaisResponse.data);
          setAulas(aulasResponse.data);
        } catch (error) {
          console.error("Erro ao carregar dados:", error);
        }
      };
      carregarDados();
    }
  }, [cursoSelecionado]);

  // Adicionar nova aula
  const adicionarAula = async () => {
    if (!novaAula.titulo || !novaAula.arquivo || !cursoSelecionado) {
      alert("Preencha todos os campos obrigatórios");
      return;
    }

    const formData = new FormData();
    formData.append("titulo", novaAula.titulo);
    formData.append("video", novaAula.arquivo);
    formData.append("cursoId", cursoSelecionado);

    try {
      await axios.post("/api/aulas", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });
      alert("Aula adicionada com sucesso!");
      setNovaAula({ titulo: "", arquivo: null });

      // Recarregar aulas
      const response = await axios.get(`/api/aulas/curso/${cursoSelecionado}`);
      setAulas(response.data);
    } catch (error) {
      console.error("Erro ao adicionar aula:", error);
      alert("Erro ao adicionar aula");
    }
  };

  // Adicionar novo material
  const adicionarMaterial = async () => {
    if (!novoMaterial.nome || !novoMaterial.arquivo || !cursoSelecionado) {
      alert("Preencha todos os campos obrigatórios");
      return;
    }

    const formData = new FormData();
    formData.append("nome", novoMaterial.nome);
    formData.append("arquivo", novoMaterial.arquivo);
    formData.append("cursoId", cursoSelecionado);

    try {
      await axios.post("/api/materiais", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });
      alert("Material adicionado com sucesso!");
      setNovoMaterial({ nome: "", arquivo: null });

      // Recarregar materiais
      const response = await axios.get(
        `/api/materiais/curso/${cursoSelecionado}`
      );
      setMateriais(response.data);
    } catch (error) {
      console.error("Erro ao adicionar material:", error);
      alert("Erro ao adicionar material");
    }
  };

  // Remover material
  const removerMaterial = async (id) => {
    try {
      await axios.delete(`/api/materiais/${id}`);
      setMateriais(materiais.filter((material) => material.id !== id));
    } catch (error) {
      console.error("Erro ao remover material:", error);
    }
  };

  // Remover aula
  const removerAula = async (id) => {
    try {
      await axios.delete(`/api/aulas/${id}`);
      setAulas(aulas.filter((aula) => aula.id !== id));
    } catch (error) {
      console.error("Erro ao remover aula:", error);
    }
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      {/* ... (código anterior do nav) ... */}

      <h2 className="mb-3 text-center">Aulas</h2>
      <div className="d-flex justify-content-between w-75">
        <div>
          <h4>Aulas Ao Vivo</h4>
          <div className="card p-3">
            <img src={live} alt="Aula ao vivo" className="img-fluid" />
            <div className="d-flex justify-content-between mt-2">
              <button className="btn btn-primary">Entrar</button>
              <button className="btn btn-secondary">+ Nova Reunião</button>
            </div>
          </div>
        </div>
        <div>
          <div className="d-flex justify-content-between align-items-center mb-2">
            <h4>Aulas Gravadas</h4>
          </div>
          <div className="d-flex mb-2">
            <select
              className="form-select me-2"
              value={cursoSelecionado}
              onChange={(e) => setCursoSelecionado(e.target.value)}
            >
              <option value="">Selecione o Curso</option>
              {cursos.map((curso) => (
                <option key={curso.id} value={curso.id}>
                  {curso.nome}
                </option>
              ))}
            </select>
          </div>

          {/* Formulário para adicionar nova aula */}
          {cursoSelecionado && (
            <div className="card p-3 mb-3">
              <h5>Adicionar Nova Aula</h5>
              <div className="mb-3">
                <label className="form-label">Título da Aula</label>
                <input
                  type="text"
                  className="form-control"
                  value={novaAula.titulo}
                  onChange={(e) =>
                    setNovaAula({ ...novaAula, titulo: e.target.value })
                  }
                />
              </div>
              <div className="mb-3">
                <label className="form-label">Vídeo da Aula</label>
                <input
                  type="file"
                  className="form-control"
                  accept="video/*"
                  onChange={(e) =>
                    setNovaAula({ ...novaAula, arquivo: e.target.files[0] })
                  }
                />
              </div>
              <button className="btn btn-primary" onClick={adicionarAula}>
                Enviar Aula
              </button>
            </div>
          )}

          {/* Lista de aulas */}
          {cursoSelecionado && (
            <table className="table table-bordered bg-white">
              <tbody>
                {aulas.map((aula) => (
                  <tr key={aula.id}>
                    <td>
                      <a
                        href={aula.videoUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        {aula.titulo}
                      </a>
                    </td>
                    <td>
                      <button
                        className="btn btn-link text-danger"
                        onClick={() => removerAula(aula.id)}
                      >
                        🗑
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* Seção de Materiais de Apoio */}
      {cursoSelecionado && (
        <div className="mt-4 w-75">
          <h4>Material de Apoio</h4>
          <div className="card p-3">
            <div className="mb-3">
              <label className="form-label">Nome do Material</label>
              <input
                type="text"
                className="form-control"
                value={novoMaterial.nome}
                onChange={(e) =>
                  setNovoMaterial({ ...novoMaterial, nome: e.target.value })
                }
              />
            </div>
            <input
              type="file"
              className="form-control mb-3"
              accept=".pdf,.doc,.docx,.ppt,.pptx"
              onChange={(e) =>
                setNovoMaterial({ ...novoMaterial, arquivo: e.target.files[0] })
              }
            />
            <button
              className="btn btn-primary mb-3"
              onClick={adicionarMaterial}
            >
              Adicionar Material
            </button>

            <ul className="list-group">
              {materiais.map((material) => (
                <li
                  key={material.id}
                  className="list-group-item d-flex justify-content-between align-items-center"
                >
                  <a
                    href={material.arquivoUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    {material.nome}
                  </a>
                  <button
                    className="btn btn-link text-danger"
                    onClick={() => removerMaterial(material.id)}
                  >
                    🗑
                  </button>
                </li>
              ))}
            </ul>
          </div>
        </div>
      )}
    </div>
  );
};

export default LecionaAula;
